import content from './guide-content.json';

/**
 * Written walkthrough ("Guide"). The content (steps, screenshots, highlight
 * boxes) is generated by marketing/walkthrough from the real site, so the
 * pictures match the UI. Customer and creator chapters are public (/guide);
 * admin chapters live behind requireAdmin (/admin/guide).
 */
export type GuideAudience = 'customer' | 'creator' | 'admin';

export interface GuideBox {
  /** Fractions of the image (0–1). */
  x: number;
  y: number;
  w: number;
  h: number;
}

export interface GuideStep {
  title: string;
  body: string;
  image: string | null;
  width: number;
  height: number;
  box: GuideBox | null;
  href?: string;
}

export interface GuideChapter {
  slug: string;
  audience: GuideAudience;
  title: string;
  summary: string;
  steps: GuideStep[];
}

const CHAPTERS = (content as { chapters: GuideChapter[] }).chapters;

export const GUIDE_GROUPS: Record<GuideAudience, string> = {
  customer: 'Shopping & your account',
  creator: 'For creators',
  admin: 'Running the store',
};

export function guideChapters(audiences: GuideAudience[]): GuideChapter[] {
  return CHAPTERS.filter((c) => audiences.includes(c.audience));
}

export function guideChapter(slug: string, audiences: GuideAudience[]): GuideChapter | null {
  return CHAPTERS.find((c) => c.slug === slug && audiences.includes(c.audience)) ?? null;
}

/** Previous / next chapter within the same set of audiences. */
export function guideNeighbours(slug: string, audiences: GuideAudience[]) {
  const list = guideChapters(audiences);
  const i = list.findIndex((c) => c.slug === slug);
  return { prev: i > 0 ? list[i - 1]! : null, next: i >= 0 && i < list.length - 1 ? list[i + 1]! : null };
}

export const stepAnchor = (i: number) => `step-${i + 1}`;
